     "tex": "\\begin{array}{|l|l|}\n\\hline\n\\textbf{Core Concept / Operator} & \\textbf{Master Formula / Analytical Condition} \\\\ \\hline\n\\text{Continuous Convolution Integral} & y(t) = \\int_{-\\infty}^\\infty x(\\tau)h(t-\\tau)d\\tau = \\int_{-\\infty}^\\infty h(\\tau)x(t-\\tau)d\\tau \\\\ \\hline\n\\text{Discrete Convolution Sum} & y[n] = \\sum_{k=-\\infty}^\\infty x[k]h[n-k] = \\sum_{k=-\\infty}^\\infty h[k]x[n-k] \\\\ \\hline\n\\text{Area Conservation Theorem} & \\int_{-\\infty}^\\infty y(t)dt = \\left[\\int_{-\\infty}^\\infty x(t)dt\\right] \\cdot \\left[\\int_{-\\infty}^\\infty h(t)dt\\right] \\\\ \\hline\n\\text{Summation Conservation Law} & \\sum_{n=-\\infty}^\\infty y[n] = \\left[\\sum_{n=-\\infty}^\\infty x[n]\\right] \\cdot \\left[\\sum_{n=-\\infty}^\\infty h[n]\\right] \\\\ \\hline\n\\text{Continuous Duration Law} & \\text{Support}(y) = [t_{x1}+t_{h1}, t_{x2}+t_{h2}], \\quad W_y = W_x + W_h \\\\ \\hline\n\\text{Discrete Length Law} & L_y = L_x + L_h - 1 \\\\ \\hline\n\\text{Derivative Convolution Engine} & \\frac{d^{m+n}y(t)}{dt^{m+n}} = \\frac{d^m x(t)}{dt^m} * \\frac{d^n h(t)}{dt^n} \\\\ \\hline\n\\text{Affine Scaling Formula} & x(at+b) * h(at+c) = \\frac{1}{|a|} y(at+b+c) \\quad (\\text{Requires identical } a) \\\\ \\hline\n\\text{Equal Rectangles Convolution} & \\text{rect}(t/W) * \\text{rect}(t/W) = W \\cdot \\text{tri}(t/W) \\quad (\\text{Base } 2W, \\text{Peak } W) \\\\ \\hline\n\\text{Unequal Rectangles Convolution} & \\text{Base } W_1+W_2, \\quad \\text{Flat Top } |W_2-W_1|, \\quad \\text{Peak } A_1 A_2 \\min(W_1, W_2) \\\\ \\hline\n\\text{Singularity Convolutions} & u(t)*u(t) = r(t); \\quad u(t)*r(t) = \\frac{t^2}{2}u(t); \\quad r(t)*r(t) = \\frac{t^3}{6}u(t) \\\\ \\hline\n\\text{Discrete Singularity Convolution} & u[n]*u[n] = (n+1)u[n] = r[n+1] \\\\ \\hline\n\\text{CT Response Ladder} & h(t) = \\frac{ds(t)}{dt} = \\frac{d^2 c(t)}{dt^2}; \\quad s(t) = \\int_{-\\infty}^t h(\\tau)d\\tau \\\\ \\hline\n\\text{DT Response Ladder} & h[n] = s[n] - s[n-1] = \\nabla^2 c[n]; \\quad s[n] = \\sum_{k=-\\infty}^n h[k] \\\\ \\hline\n\\text{Closed-Loop Negative Feedback} & H_{\\text{closed}}(s) = \\frac{G(s)}{1 + G(s)H(s)}; \\quad H_{\\text{closed}}(z) = \\frac{G(z)}{1 + G(z)H(z)} \\\\ \\hline\n\\text{Closed-Loop Positive Feedback} & H_{\\text{closed}}(s) = \\frac{G(s)}{1 - G(s)H(s)}; \\quad H_{\\text{closed}}(z) = \\frac{G(z)}{1 - G(z)H(z)} \\\\ \\hline\n\\end{array}"
